def minimum_or_after_and_merges(nums,k):
    answer=forbidden=0
    for bit in range(29,-1,-1):
        candidate=forbidden|(1<<bit);segments=0;running=candidate
        for value in nums:
            running&=value
            if running==0:segments+=1;running=candidate
        if len(nums)-segments<=k:forbidden=candidate
        else:answer|=1<<bit
    return answer

